SELECT 'printings' AS scope,id::text AS identity,to_jsonb(t) AS payload FROM catalog.card_printings t WHERE id=ANY(ARRAY['36710a9b-7b22-4412-b2a9-2fb4af5aeb7c','e6192b59-9593-4315-a414-591df5f3fe51','c61d1e2b-a65c-4b2a-bce6-6f66d236b4fb']::uuid[]) UNION ALL SELECT 'variants',id::text,to_jsonb(t) FROM catalog.card_variants t WHERE printing_id=ANY(ARRAY['36710a9b-7b22-4412-b2a9-2fb4af5aeb7c','e6192b59-9593-4315-a414-591df5f3fe51','c61d1e2b-a65c-4b2a-bce6-6f66d236b4fb']::uuid[]) UNION ALL SELECT 'names',id::text,to_jsonb(t) FROM catalog.card_names t WHERE printing_id=ANY(ARRAY['36710a9b-7b22-4412-b2a9-2fb4af5aeb7c','e6192b59-9593-4315-a414-591df5f3fe51','c61d1e2b-a65c-4b2a-bce6-6f66d236b4fb']::uuid[]) OR variant_id=ANY(ARRAY['fe011d15-fd0e-46ef-b420-d95348d67754','bf6f9b6b-1597-4526-8104-adcc0e460d54','0ee290c9-af9e-4d82-8cd0-a0d15dbee95e']::uuid[]) UNION ALL SELECT 'sets',id::text,to_jsonb(t) FROM catalog.sets t WHERE id=ANY(ARRAY['9fa08d47-d2cd-4829-85b6-819692a6850a']::uuid[]) UNION ALL SELECT 'sources',id::text,to_jsonb(t) FROM ingest.sources t WHERE (code IN ('scrydex','pokellector','tcgcollector','pricecharting') OR lower(base_url) LIKE '%pokellector.com%' OR lower(base_url) LIKE '%tcgcollector.com%' OR lower(base_url) LIKE '%pricecharting.com%') UNION ALL SELECT 'assets',id::text,to_jsonb(t) FROM catalog.assets t WHERE printing_id=ANY(ARRAY['36710a9b-7b22-4412-b2a9-2fb4af5aeb7c','e6192b59-9593-4315-a414-591df5f3fe51','c61d1e2b-a65c-4b2a-bce6-6f66d236b4fb']::uuid[]) OR variant_id=ANY(ARRAY['fe011d15-fd0e-46ef-b420-d95348d67754','bf6f9b6b-1597-4526-8104-adcc0e460d54','0ee290c9-af9e-4d82-8cd0-a0d15dbee95e']::uuid[]) OR (printing_id IS NULL AND variant_id IS NULL AND set_id=ANY(ARRAY['9fa08d47-d2cd-4829-85b6-819692a6850a']::uuid[])) UNION ALL SELECT 'links',catalogue_version_id::text||':'||asset_id::text,to_jsonb(t) FROM catalog.catalogue_version_assets t WHERE printing_id=ANY(ARRAY['36710a9b-7b22-4412-b2a9-2fb4af5aeb7c','e6192b59-9593-4315-a414-591df5f3fe51','c61d1e2b-a65c-4b2a-bce6-6f66d236b4fb']::uuid[]) OR variant_id=ANY(ARRAY['fe011d15-fd0e-46ef-b420-d95348d67754','bf6f9b6b-1597-4526-8104-adcc0e460d54','0ee290c9-af9e-4d82-8cd0-a0d15dbee95e']::uuid[]) OR asset_id IN(SELECT id FROM catalog.assets WHERE printing_id=ANY(ARRAY['36710a9b-7b22-4412-b2a9-2fb4af5aeb7c','e6192b59-9593-4315-a414-591df5f3fe51','c61d1e2b-a65c-4b2a-bce6-6f66d236b4fb']::uuid[]) OR variant_id=ANY(ARRAY['fe011d15-fd0e-46ef-b420-d95348d67754','bf6f9b6b-1597-4526-8104-adcc0e460d54','0ee290c9-af9e-4d82-8cd0-a0d15dbee95e']::uuid[]) OR (printing_id IS NULL AND variant_id IS NULL AND set_id=ANY(ARRAY['9fa08d47-d2cd-4829-85b6-819692a6850a']::uuid[]))) OR(printing_id IS NULL AND variant_id IS NULL AND set_id=ANY(ARRAY['9fa08d47-d2cd-4829-85b6-819692a6850a']::uuid[])) ORDER BY scope,identity;